let overflowBuffer = [];

if (fs.existsSync(overflowPath)) {
  try {
    const rawData = fs.readFileSync(overflowPath, 'utf8');
    overflowBuffer = JSON.parse(rawData || '[]');
  } catch (e) {
    console.error("Error reading overflow file:", e);
    overflowBuffer = [];
  }
}

if (overflowBuffer.length === 0) {
  return []; // Stops execution if queue is empty
}

// Return formatted array instructing n8n to split into individual items
return overflowBuffer.map(paper => ({
  json: {
    title: paper.title || "Untitled Paper",
    authors: paper.authors || "Unknown Authors",
    arxivId: paper.arxivId,
    url: paper.url || `https://arxiv.org/abs/${paper.arxivId}`,
    rationale: paper.rationale || "No rationale provided."
  }
}));

const fs = require('fs');
const path = require('path');

const overflowPath = path.join('/data', 'arxiv_overflow.json');

// 1. Extract minimal payload sent from Mattermost button context
const payload = $input.all()[0]?.json?.body?.context || {};
const targetArxivId = payload.arxivId;
const action = payload.action; // 'keep' or 'discard'

let overflowBuffer = [];

// 2. Read the overflow file safely
if (fs.existsSync(overflowPath)) {
  try {
    const rawData = fs.readFileSync(overflowPath, 'utf8');
    overflowBuffer = JSON.parse(rawData || '[]');
  } catch (e) {
    console.error("Error reading overflow file:", e);
    overflowBuffer = [];
  }
}

// 3. Find the paper before removing it (to retain details like title/url)
const targetPaper = overflowBuffer.find(paper => paper.arxivId === targetArxivId) || {};

// 4. Remove the paper from the buffer
const initialLength = overflowBuffer.length;
const updatedBuffer = overflowBuffer.filter(paper => paper.arxivId !== targetArxivId);

// 5. Overwrite the file back to disk
if (updatedBuffer.length !== initialLength) {
  try {
    fs.writeFileSync(overflowPath, JSON.stringify(updatedBuffer, null, 2), 'utf8');
  } catch (e) {
    console.error("Error writing updated overflow file:", e);
  }
}

// 6. Return enriched payload for downstream nodes
return [{
  json: {
    action: action,
    arxivId: targetArxivId,
    title: targetPaper.title || targetArxivId || "Paper",
    url: targetPaper.url || `https://arxiv.org/abs/${targetArxivId}`,
    authors: targetPaper.authors || "",
    rationale: targetPaper.rationale || "",
    remainingCount: updatedBuffer.length
  }
}];

