const paper = $input.first().json;

// 1. Normalize authors into an array
let authorsList = [];
if (Array.isArray(paper.authors)) {
  authorsList = paper.authors;
} else if (typeof paper.authors === 'string' && paper.authors.trim() !== '') {
  authorsList = paper.authors.split(',').map(a => a.trim()).filter(Boolean);
} else {
  authorsList = ['Unknown'];
}

// 2. Ensure embedding is a stringified JSON array or explicit null
const embeddingVector = Array.isArray(paper.embedding)
  ? JSON.stringify(paper.embedding)
  : (paper.embedding || null);

return {
  tier: paper.tier || 'Tier 1',
  source: paper.source || 'manual',
  arxiv_id: paper.arxiv_id || null,
  doi: paper.doi || null,
  title: paper.title || 'Untitled',
  authors: JSON.stringify(authorsList), // JSON array string, e.g. '["Ada Lovelace", "Alan Turing"]'
  abstract: paper.abstract || '',
  url: paper.url || (paper.arxiv_id ? `https://arxiv.org/abs/${paper.arxiv_id}` : null),
  embedding: embeddingVector,
  metadata: {
    ingested_at: new Date().toISOString(),
    source_type: paper.source || 'manual'
  }
};

function normalizeName(name) {
  const parts = name.replace(/[^a-zA-Z\s]/g, '').trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return '';
  if (parts.length === 1) return parts[0].toLowerCase();

  const lastName = parts[parts.length - 1].toLowerCase();
  const firstInitial = parts[0][0].toLowerCase();
  return `${firstInitial}_${lastName}`;
}

function parseAuthors(authors) {
  if (!authors) return [];
  if (Array.isArray(authors)) return authors;
  if (typeof authors !== 'string') return [];

  // 1. Try JSON parsing if it's a stringified JSON array
  try {
    const parsed = JSON.parse(authors);
    if (Array.isArray(parsed)) return parsed;
  } catch (e) {
    // Not JSON, continue to fallback string parsing
  }

  // 2. Handle Postgres literal format {"Author 1", "Author 2"}
  let str = authors.trim();
  if (str.startsWith('{') && str.endsWith('}')) {
    str = str.slice(1, -1);
  }

  // 3. Split by comma and strip quotes, brackets, braces, and trailing spaces
  return str
    .split(',')
    .map(a => a.replace(/^[\s"\[\{]+|[\s"\]\}]+$/g, '').trim())
    .filter(Boolean);
}

const paper = $('Normalize Paper Output').item.json;

if (paper.tier === 'Tier 3' || !paper.authors) {
  return [];
}

const targetTier = paper.tier;
const authorList = parseAuthors(paper.authors);

return authorList
  .map(cleanName => {
    return {
      json: {
        author_name: cleanName,
        normalized_name: normalizeName(cleanName),
        tier: targetTier
      }
    };
  })
  .filter(item => item.json.normalized_name.length > 0);

const paper = $('Normalize Paper Output').item.json;
const vectorArray = $input.item.json.embedding;

// Extract database top-level columns; bundle remaining metadata into payload
const { tier, arxiv_id, doi, ...metadata } = paper;

return {
  tier: tier || null,
  arxiv_id: arxiv_id || null,
  doi: doi || null,
  embedding: JSON.stringify(vectorArray),
  payload: JSON.stringify(metadata)
};

const input = $input.item.json;
const rawInput = input["arXiv Link or ID"] || '';
const match = rawInput.match(/(\d{4}\.\d{4,5}|[a-z\-]+(?:\.[A-Z]{2})?\/\d{7})/);

if (!match) {
  throw new Error("Could not extract a valid arXiv ID from input.");
}

return {
  clean_id: match[1],
  tier: input["Target Tier"] || 'Tier 1',
  doi: input["DOI"] || null
};

const xml = $input.item.json.data || $input.item.json.body || '';
const parentData = $('Clean arXiv ID').item.json;
const cleanId = parentData.clean_id;

const titleMatch = xml.match(/<entry>[\s\S]*?<title>([\s\S]*?)<\/title>/);
const title = titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : '';

const abstractMatch = xml.match(/<entry>[\s\S]*?<summary>([\s\S]*?)<\/summary>/);
const abstract = abstractMatch ? abstractMatch[1].replace(/\s+/g, ' ').trim() : '';

const authorMatches = [...xml.matchAll(/<author>[\s\S]*?<name>([\s\S]*?)<\/name>/g)];
const authors = authorMatches.map(m => m[1].trim()).join(', ');

if (!title) {
  throw new Error(`No paper details found for arXiv ID: ${cleanId}`);
}

return {
  title,
  authors,
  abstract,
  arxiv_id: cleanId,
  doi: parentData.doi || null,
  tier: parentData.tier || 'Tier 1',
  source: 'arxiv',
  url: `https://arxiv.org/abs/${cleanId}`
};

const input = $input.item.json;
const rawBibtex = input["BibTeX Entry"] || '';

function getBibField(field, text) {
  const fieldRegex = new RegExp(`\\b${field}\\s*=\\s*`, 'i');
  const match = text.match(fieldRegex);
  if (!match) return '';

  const startIdx = match.index + match[0].length;
  const char = text[startIdx];

  if (char === '{') {
    let depth = 0;
    for (let i = startIdx; i < text.length; i++) {
      if (text[i] === '{') depth++;
      else if (text[i] === '}') depth--;

      if (depth === 0) {
        return text.slice(startIdx + 1, i).replace(/\s+/g, ' ').trim();
      }
    }
  } else if (char === '"') {
    const endIdx = text.indexOf('"', startIdx + 1);
    if (endIdx !== -1) {
      return text.slice(startIdx + 1, endIdx).replace(/\s+/g, ' ').trim();
    }
  } else {
    const endMatch = text.slice(startIdx).match(/^([^,}]+)/);
    if (endMatch) return endMatch[1].replace(/\s+/g, ' ').trim();
  }
  return '';
}

function cleanText(text) {
  if (!text) return '';
  return text
    .replace(/\\['"`^~v=.c]?\{?([a-zA-Z])\}?/g, '$1') // Normalize LaTeX accents
    .replace(/[{}]/g, '')                             // Strip braces
    .replace(/\\/g, '')                              // Strip remaining backslashes
    .replace(/\s+/g, ' ')                            // Normalize spaces
    .trim();
}

function formatAuthorName(author) {
  const clean = cleanText(author);
  if (clean.includes(',')) {
    const parts = clean.split(',').map(p => p.trim()).filter(Boolean);
    const lastName = parts[0];
    const firstNames = parts.slice(1).join(' ');
    return firstNames ? (firstNames + ' ' + lastName) : lastName;
  }
  return clean;
}

const title = cleanText(getBibField('title', rawBibtex));
const rawAuthors = getBibField('author', rawBibtex) || getBibField('authors', rawBibtex) || 'Unknown';
const authors = rawAuthors.split(/\s+and\s+/i).map(formatAuthorName).join(', ');
const abstract = cleanText(getBibField('abstract', rawBibtex));

let arxiv_id = getBibField('eprint', rawBibtex);
if (!arxiv_id) {
  const idMatch = rawBibtex.match(/(\d{4}\.\d{4,5}|[a-z\-]+(?:\.[A-Z]{2})?\/\d{7})/);
  arxiv_id = idMatch ? idMatch[1] : null;
}

const doi = input["DOI"] || getBibField('doi', rawBibtex) || null;

if (!title) {
  throw new Error("Could not parse a valid 'title' from the BibTeX string. Check format.");
}

return {
  title,
  authors,
  abstract: abstract || "No abstract provided.",
  arxiv_id,
  doi,
  tier: input["Target Tier"] || 'Tier 1',
  source: 'bibtex',
  url: arxiv_id 
    ? `https://arxiv.org/abs/${arxiv_id}` 
    : (doi ? `https://doi.org/${doi}` : null)
};

const input = $input.item.json;

return {
  title: (input["Paper Title"] || '').trim(),
  authors: (input["Authors"] || 'Unknown').trim(),
  abstract: (input["Abstract"] || '').trim(),
  arxiv_id: (input["arXiv Link or ID"] || '').trim() || null,
  doi: (input["DOI"] || '').trim() || null,
  tier: input["Target Tier"] || 'Tier 1',
  source: 'manual',
  url: null
};

const translator = String($env.ZOTERO_TRANSLATOR_URL || 'http://zotero-translator:1969').match(/^https?:\/\/([^:\/]+)(?::(\d+))?/) || [];
const http = require('http');

// 1. Build a resilient fallback cascade to get a clean identifier Zotero loves
// Checks for native Postgres snake_case, camelCase, or Semantic Scholar API nested IDs
const identifier = $json.doi 
  || $json.arxiv_id 
  || $json.arxivId 
  || ($json.externalIds ? $json.externalIds.ArXiv : null);

// 2. Guard Clause: If no valid ID exists, or it's a Semantic Scholar URL, exit gracefully
if (!identifier || String(identifier).includes('semanticscholar.org')) {
  return { 
    json: { 
      success: false, 
      reason: "Skipped: No clean DOI or arXiv ID available for Zotero translation." 
    } 
  };
}

const fetchMetadata = (id) => {
  return new Promise((resolve, reject) => {
    const payload = String(id).trim();

    const options = {
      hostname: translator[1],
      port: Number(translator[2] || 80),
      path: '/search',
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let rawData = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => { rawData += chunk; });

      res.on('end', () => {
        try {
          if (res.statusCode !== 200) {
            return reject(new Error(`Zotero translation server returned status ${res.statusCode}`));
          }
          const parsedData = JSON.parse(rawData);
          resolve(parsedData[0] || parsedData);
        } catch (e) {
          reject(e);
        }
      });
    });

    req.on('error', (e) => reject(e));
    req.write(payload);
    req.end();
  });
};

try {
  const result = await fetchMetadata(identifier);

  if (result && typeof result === 'object') {
    result.collections = [$env.ZOTERO_COLLECTION_KEY];
  }

  return { json: { success: true, data: result } };
} catch (error) {
  // Return the error as data instead of crashing the whole workflow execution thread
  return { 
    json: { 
      success: false, 
      error: error.message,
      attemptedIdentifier: identifier
    } 
  };
}

function normalizeName(name) {
  const parts = name.replace(/[^a-zA-Z\s]/g, '').trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return '';
  if (parts.length === 1) return parts[0].toLowerCase();

  const lastName = parts[parts.length - 1].toLowerCase();
  const firstInitial = parts[0][0].toLowerCase();
  return `${firstInitial}_${lastName}`;
}

function parseAuthors(authors) {
  if (!authors) return [];
  if (Array.isArray(authors)) return authors;
  if (typeof authors !== 'string') return [];

  try {
    const parsed = JSON.parse(authors);
    if (Array.isArray(parsed)) return parsed;
  } catch (e) {}

  let str = authors.trim();
  if (str.startsWith('{') && str.endsWith('}')) {
    str = str.slice(1, -1);
  }

  return str
    .split(',')
    .map(a => a.replace(/^[\s"\[\{]+|[\s"\]\}]+$/g, '').trim())
    .filter(Boolean);
}

// 1. Grab input directly from the preceding Wait Form node
const formData = $input.first().json;

// Extract values from form keys
const rawNameInput = formData['Name'] || formData.name || '';
const targetTier = formData['Target Tier'] || formData.tier || 'Tier 2';

if (!rawNameInput) {
  return [];
}

const authorList = parseAuthors(rawNameInput);

return authorList
  .map(cleanName => {
    const norm = normalizeName(cleanName);
    return {
      json: {
        author_name: cleanName,
        normalized_name: norm,
        tier: targetTier
      }
    };
  })
  .filter(item => item.json.normalized_name.length > 0);

// Helper function to extract a valid string value, filtering out "null", "undefined", etc.
function cleanVal(val) {
  if (val === null || val === undefined) return '';
  const str = String(val).trim();
  if (str === '' || str.toLowerCase() === 'null' || str.toLowerCase() === 'undefined') {
    return '';
  }
  return str;
}

// 1. Ingest input array
const rawData = $input.all().map(item => item.json);

// Separate items into Papers and Authors dynamically
const papers = rawData.filter(item => item.title !== undefined);
const authors = rawData.filter(item => item.author_name !== undefined);

// 2. Build Papers Markdown Table
let paperMarkdown = '### 📚 Curated Papers\n';
if (papers.length === 0) {
  paperMarkdown += '*No papers found in database.*\n\n';
} else {
  paperMarkdown += '| Identifier | Tier | Title |\n| :--- | :--- | :--- |\n';
  papers.forEach(p => {
    const arxivId = cleanVal(p.arxiv_id);
    const doi = cleanVal(p.doi);

    // Priority: arXiv ID -> DOI -> N/A
    let id = 'N/A';
    if (arxivId !== '') {
      id = arxivId;
    } else if (doi !== '') {
      id = doi;
    }

    const tier = cleanVal(p.tier) || 'N/A';
    const title = (cleanVal(p.title) || 'Untitled').replace(/\|/g, '\\|');
    paperMarkdown += `| ${id} | ${tier} | ${title} |\n`;
  });
  paperMarkdown += '\n';
}

// 3. Build Authors Markdown Table
let authorMarkdown = '### 👤 Known Authors\n';
if (authors.length === 0) {
  authorMarkdown += '*No known authors found in database.*\n';
} else {
  authorMarkdown += '| Author Name | Normalized | Tier |\n| :--- | :--- | :--- |\n';
  authors.forEach(a => {
    const name = (cleanVal(a.author_name) || 'N/A').replace(/\|/g, '\\|');
    const norm = cleanVal(a.normalized_name) || 'N/A';
    const tier = cleanVal(a.tier) || 'N/A';
    authorMarkdown += `| ${name} | ${norm} | ${tier} |\n`;
  });
}

const fullMessage = paperMarkdown + authorMarkdown;

return [{
  json: {
    response_type: 'in_channel',
    text: fullMessage
  }
}];

