const context = $('Extract Callback Context').first().json;
const rawHtml = $input.first().json.data || $input.first().json.body || '';

let cleanTranscript = '';
if (typeof rawHtml === 'string') {
  cleanTranscript = rawHtml
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// If fetch failed or returned 404, fall back to vector chunk snippet
if (cleanTranscript.length < 50) {
  cleanTranscript = context.snippet || 'No transcript available.';
}

// Safety context limit for LLM
if (cleanTranscript.length > 25000) {
  cleanTranscript = cleanTranscript.slice(0, 25000) + '... [Transcript truncated]';
}

return [{
  json: {
    query: context.query,
    title: context.title,
    paper_link: context.paper_link,
    channel_id: context.channel_id,
    cleanTranscript: cleanTranscript
  }
}];

const pub = String($env.PODCAST_PUBLIC_URL || '').replace(/\/+$/, '');
const internal = String($env.PODCAST_INTERNAL_URL || '').replace(/\/+$/, '');
const toInternal = (u) => (pub && internal && u.startsWith(pub)) ? internal + u.slice(pub.length) : u;

const body = $json.body || {};
const context = body.context || {};

return [{
  json: {
    query: context.query || 'Podcast query',
    title: context.title || 'Episode',
    paper_link: context.paper_link || '',
    // Fetch transcripts over the internal Docker network instead of the public URL
    transcript_url: toInternal(context.transcript_url || ''),
    snippet: context.snippet || '',
    channel_id: context.channel_id || body.channel_id || $env.MATTERMOST_CHANNEL_ID
  }
}];

const params = $('Normalize Search Params').first().json;
const rawItems = $input.all();

const query = params.query;
const channelId = params.channelId || $env.MATTERMOST_CHANNEL_ID;
const hook = String($env.WEBHOOK_URL || '').replace(/\/+$/, '') + '/webhook';
const offset = params.offset || 0;
const postId = params.postId || '';
const limit = 3;

// 1. Unpack Qdrant LangChain nested document structure
const normalizedItems = rawItems.map(item => {
  const doc = item.json.document || item.json;
  const metadata = doc.metadata || item.json.metadata || {};
  const pageContent = (doc.pageContent || item.json.pageContent || '').trim();
  const score = item.json.score !== undefined ? item.json.score : doc.score;

  return {
    pageContent,
    metadata,
    score: score || 0
  };
});

// 2. Filter out empty items
const validRaw = normalizedItems.filter(item => item.pageContent.length > 10);

// 3. Deduplicate / Group by Paper
const uniquePapersMap = new Map();

for (const item of validRaw) {
  const metadata = item.metadata || {};
  const snippet = item.pageContent;

  const arxivMatch = (metadata.title || snippet).match(/arXiv:\s*(\d{4}\.\d{4,5})/i);
  const arxivId = metadata.arxiv_id || (arxivMatch ? arxivMatch[1] : null);

  let title = metadata.title;
  if (!title || metadata.source === 'blob') {
    const titleMatch = snippet.match(/^(Briefing|Breakdown|Deep Dive)\s*-\s*([^\n(]+)/i);
    if (titleMatch) {
      const cleanTitlePart = titleMatch[2].replace(/-\s*Transcript.*/i, '').trim();
      title = `${titleMatch[1]} - ${cleanTitlePart}`;
    } else if (arxivId) {
      title = `arXiv:${arxivId} Episode`;
    } else {
      continue;
    }
  }

  const dedupeKey = arxivId ? `arxiv_${arxivId}` : `title_${title.toLowerCase()}`;
  const tldr = metadata.tldr || metadata.description || '';

  if (!uniquePapersMap.has(dedupeKey)) {
    uniquePapersMap.set(dedupeKey, {
      title,
      arxivId,
      metadata,
      tldr,
      bestScore: item.score,
      bestSnippet: snippet
    });
  } else {
    const existing = uniquePapersMap.get(dedupeKey);
    const isMoreInformativeChunk = snippet.length > 120 && existing.bestSnippet.length < 120;
    const isHigherScore = item.score > existing.bestScore;

    if (isHigherScore) {
      existing.bestScore = item.score;
    }
    if (isMoreInformativeChunk || (isHigherScore && snippet.length > 100)) {
      existing.bestSnippet = snippet;
    }
    if (!existing.tldr && tldr) {
      existing.tldr = tldr;
    }
  }
}

const validResults = Array.from(uniquePapersMap.values());
const totalResults = validResults.length;

if (totalResults === 0) {
  return [{
    json: {
      postId: postId,
      channelId: channelId,
      message: `⚠️ No matching podcast episodes found for **"${query}"**.`,
      attachments: []
    }
  }];
}

// 4. Slice for current page
const pageResults = validResults.slice(offset, offset + limit);

// 5. Build Mattermost attachment cards
const attachments = pageResults.map((paper, idx) => {
  const itemNum = offset + idx + 1;
  const metadata = paper.metadata || {};
  const snippet = paper.bestSnippet;
  const arxivId = paper.arxivId;
  const title = paper.title;

  const paperLink = metadata.link || (arxivId ? `https://arxiv.org/abs/${arxivId}` : null);
  const transcriptUrl = metadata.transcript_url || '';
  const scoreBadge = paper.bestScore ? `*(Match Score: ${(paper.bestScore * 100).toFixed(0)}%)*` : '';

  // Get TL;DR (prevent raw chunk fallback that prints titles)
  let tldr = paper.tldr || metadata.tldr || metadata.description;
  if (!tldr || tldr.trim() === '') {
    const tldrMatch = snippet.match(/(?:TL;?DR|Summary)[:\s\-]+([^.]+?\.)/i);
    tldr = tldrMatch ? tldrMatch[1].trim() : 'No summary available.';
  }

  const linkRow = paperLink ? `[📄 View Paper](${paperLink})` : '';

  const actions = [
    {
      id: `explain_${idx}`,
      name: "💡 Explain",
      type: "button",
      integration: {
        url: `${hook}/llm-search-harder`,
        context: {
          query: query,
          title: title,
          paper_link: paperLink || '',
          transcript_url: transcriptUrl,
          snippet: snippet,
          channel_id: channelId
        }
      }
    }
  ];

  return {
    color: "#1665D8",
    title: `🎙️ #${itemNum}: ${title}`,
    title_link: paperLink || '',
    text: `**TL;DR:** ${tldr}\n\n${scoreBadge}${linkRow ? `\n\n${linkRow}` : ''}`,
    actions: actions
  };
});

// 6. Pagination Button
const nextOffset = offset + limit;
if (nextOffset < totalResults) {
  const remaining = totalResults - nextOffset;
  const nextBatchCount = Math.min(limit, remaining);

  attachments.push({
    color: "#28A745",
    title: `⏩ More Matches Available`,
    text: `Showing ${offset + 1}–${offset + pageResults.length} of ${totalResults} unique papers.`,
    actions: [
      {
        id: "load_next_results",
        name: `⏩ Load Next ${nextBatchCount} Papers`,
        type: "button",
        integration: {
          url: `${hook}/mattermost-search-paginate`,
          context: {
            query: query,
            channel_id: channelId,
            offset: nextOffset
          }
        }
      }
    ]
  });
}

